import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";

/**
 * @since 0.0.6
 * @status beta
 *
 * @data-testid step-indicator-{n} - A numbered paging control, where `{n}` is the 1-based slide number.
 *
 * @slot - The carousel's content
 * @slot title - The carousel's title
 * @slot footer - The carousel's footer content
 *
 * @part carousel-content - The container of the carousel's content
 * @part carousel-paging - The carousel's paging
 */
@Component({
	tag: "hbr-carousel",
	styleUrl: "carousel.scss",
	shadow: true,
})
export class Carousel {
	@Element() el: HTMLHbrCarouselElement;

	/**
	 * Position or slide where carousel will be active.
	 */
	@Prop({ mutable: true }) active = 1;

	/**
	 * Use arrows instead of button to move slides.
	 */

	@Prop() arrows = false;

	/** 'aria-label' attribute when a label is not set. */
	@Prop() arialabel;

	@State() steps: Array<Node | null> = [];

	/** Emitted when the slide position changes. */
	@Event({ eventName: "hbr-step" }) hbrStep: EventEmitter;

	handleSlotChange() {
		this.steps = this.getSlotNodes();
	}

	connectedCallback() {
		this.handlePage = this.handlePage.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	handlePage(page: number) {
		this.active = page;
		this.hbrStep.emit({ current: page });
	}

	handlePagePrevious = () => {
		if (this.active !== 0) {
			this.active = this.active - 1;
			this.hbrStep.emit({ current: this.active });
		}
	};

	keyPagePrevious = (e: KeyboardEvent) => {
		if (e.key === "Enter" || e.key === "Space") {
			this.handlePagePrevious();
			this.announceSlide();
		}
	};
	handlePageNext = () => {
		if (this.active < this.steps.length) {
			this.active = this.active + 1;
			this.hbrStep.emit({ current: this.active });
		}
	};
	keyPageNext = (e: KeyboardEvent) => {
		if (e.key === "Enter" || e.key === "Space") {
			this.handlePageNext();
			this.announceSlide();
		}
	};

	getSlotNodes() {
		return this.el.shadowRoot.querySelector("slot")?.assignedElements();
	}

	componentDidLoad() {
		this.handleSlotChange();
		if (this.steps.length > 8)
			console.warn("UX guidelines recommend max of 8 slides per carousel.");
	}
	keyPage = (page: number, event: KeyboardEvent) => {
		if (event.key === "Enter" || event.key === "Space") {
			this.handlePage(page);
			this.announceSlide();
		}
	};
	announceSlide = () => {
		if (this.el.shadowRoot?.querySelector(".liveRegion")) {
			//@ts-ignore
			this.el.shadowRoot.querySelector(".liveRegion").textContent =
				`Item ${this.active} of ${this.steps.length}`;
		}
	};

	render() {
		let leftArrow = null;
		let rightArrow = null;
		const Content = this.steps && (
			<div class="carousel-viewport">
				<div
					part="carousel-content"
					class={`carousel-content slide${this.active}`}
					aria-roledescription="carousel"
					aria-label={this.arialabel}
				>
					<slot onSlotchange={this.handleSlotChange} />
					<hbr-visually-hidden>
						<div aria-live="polite" aria-atomic="true" class="liveRegion" />
					</hbr-visually-hidden>
				</div>
			</div>
		);
		const paging = this.steps && this.steps.length > 1;
		const Title = paging && (
			<div class="carousel-title">
				<slot name="title" />
			</div>
		);
		const icon = (
			// biome-ignore lint/a11y/noSvgWithoutTitle: <explanation>
			<svg version="1.1" viewBox="0 0 24 24" width="24px" height="24px">
				<polyline
					fill="none"
					stroke="var(--body-background, #FFFFFF)"
					stroke-width="2"
					points="9 6 15 12 9 18"
				/>
			</svg>
		);
		if (this.arrows) {
			leftArrow =
				this.active === 1 ? (
					<div
						class="pagePrevious disabled"
						role="button"
						aria-disabled="true"
						tabindex="-1"
						aria-label="previous slide"
					>
						<i class="dnac-icon">{icon}</i>
					</div>
				) : (
					<div
						class="pagePrevious"
						role="button"
						tabindex="0"
						aria-label="previous slide"
						onClick={this.handlePagePrevious}
						onKeyDown={this.keyPagePrevious}
					>
						<i class="dnac-icon">{icon}</i>
					</div>
				);
			rightArrow =
				this.active === this.steps.length ? (
					<div
						class="pageNext disabled"
						role="button"
						tabindex="-1"
						aria-disabled="true"
						aria-label="next slide"
					>
						<i class="dnac-icon">{icon}</i>
					</div>
				) : (
					<div
						class="pageNext"
						onClick={this.handlePageNext}
						onKeyDown={this.keyPageNext}
						role="button"
						tabindex="0"
						aria-label="next slide"
					>
						<i class="dnac-icon">{icon}</i>
					</div>
				);
		}
		const Pager = paging && (
			<div class={"carousel-paging"} part="carousel-paging">
				{leftArrow}
				{this.steps.length > 0
					? this.steps.map(
							//@ts-ignore
							(step: HTMLElement, i) => {
								if (this.active - 1 === i && step && step.removeAttribute) {
									step.removeAttribute("aria-hidden");
									// Ensure slide itself is not focusable
									if (step.hasAttribute?.("tabindex")) {
										step.removeAttribute("tabindex");
									}
								} else if (step?.setAttribute) {
									step.setAttribute("aria-hidden", "true");
									// Remove any tabindex that might have been previously set
									if (step.hasAttribute?.("tabindex")) {
										step.removeAttribute("tabindex");
									}
								}
								const isActive = this.active === i + 1;
								return (
									<div
										class={`pageItem${isActive ? " selected" : ""}`}
										data-testid={`step-indicator-${i + 1}`}
										data-index={i}
										onClick={this.handlePage.bind(this, i + 1)}
										onKeyDown={this.keyPage.bind(this, i + 1)}
										role="button"
										tabindex="0"
										aria-label={`slide number ${i + 1}`}
										aria-current={isActive ? "true" : "false"}
									/>
								);
							},
					  )
					: null}
				{rightArrow}
			</div>
		);
		const Buttons = paging && <slot name="footer" />;
		return (
			<Host role="region" aria-label="carousel-region">
				{Content} {Title} {Pager} {Buttons}
			</Host>
		);
	}
}
